        add(name+'q',_quad(x));
    for name,x in [('u',u),('z',z),('uz',np.c_[u,z]),('zvw',np.c_[z,v,w])]:
        S=(x-x[:n].mean(0))/np.maximum(x[:n].std(0),1e-6); d=((S[:,None]-S[None,:])**2).mean(2)
